style.css:
@-moz-document domain("youtube.com") {
/* ----- FULL-PAGE BRIGHT RAINBOW BG ----- */
  body, ytd-app, #content, #page-manager {
    background: linear-gradient(
      135deg,
      #ff3b30 0%,
      #ff9500 18%,
      #ffcc00 32%,
      #34c759 48%,
      #007aff 65%,
      #5856d6 82%,
      #ff2d55 100%
    ) !important;
    color: white !important;
  }

  /* ----- SPARKLES OVERLAY ----- */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 99999;

    background:
      radial-gradient(circle, rgba(255,255,255,0.95) 0%, transparent 70%) 10% 20% / 6px 6px,
      radial-gradient(circle, rgba(255,255,255,0.95) 0%, transparent 70%) 80% 60% / 5px 5px,
      radial-gradient(circle, rgba(255,255,255,0.95) 0%, transparent 70%) 50% 80% / 8px 8px,
      repeating-linear-gradient(
        45deg,
        rgba(255,255,255,0.2) 0px,
        rgba(255,255,255,0.2) 1px,
        transparent 1px,
        transparent 4px
      );
    opacity: 0.55;

    animation: sparkleFloat 6s ease-in-out infinite alternate;
  }

  @keyframes sparkleFloat {
    from { transform: translateY(0px); }
    to   { transform: translateY(-12px); }
  }

  /* ----- TOP BAR ----- */
  ytd-masthead {
    background: rgba(255,255,255,0.25) !important;
    backdrop-filter: blur(10px);
    border-bottom: none !important;
  }

  /* ----- SEARCH BAR ----- */
  #search-input input {
    background: white !important;
    border-radius: 25px !important;
    border: 3px solid #ffffff !important;
    color: #333 !important;
    font-weight: 600;
  }

  #search-icon-legacy {
    background: white !important;
    border-radius: 25px !important;
  }

  /* ----- VIDEO CARDS (bright white to pop off rainbow bg) ----- */
  ytd-rich-item-renderer,
  ytd-video-renderer {
    background: rgba(255,255,255,0.88) !important;
    border-radius: 20px !important;
    border: 3px solid rgba(255,255,255,0.8) !important;
    box-shadow: 
      0 0 12px rgba(255,255,255,0.5),
      0 0 20px rgba(255,255,255,0.3);
  }

  /* ----- TITLES ----- */
  #video-title {
    color: #333 !important;
    font-weight: bold !important;
    text-shadow: 0 0 6px rgba(255,255,255,0.8);
  }

  /* ----- LINKS ----- */
  a, yt-formatted-string {
    color: #ffffff !important;
    text-shadow: 0 0 4px rgba(0,0,0,0.5);
  }

  /* ----- SUBSCRIBE BUTTON: RAINBOW MODE ----- */
  ytd-subscribe-button-renderer button {
    background: linear-gradient(
      90deg,
      #ff3b30,
      #ff9500,
      #ffcc00,
      #34c759,
      #007aff,
      #5856d6,
      #ff2d55
    ) !important;
    color: white !important;
    border-radius: 30px !important;
    border: none !important;
    font-weight: bold !important;
    padding: 0 18px !important;
    box-shadow: 0 0 15px rgba(255,255,255,0.7);
  }

  /* ----- COMMENTS ----- */
  #comments {
    background: rgba(255,255,255,0.85) !important;
    border-radius: 20px !important;
    border: 3px solid rgba(255,255,255,0.8) !important;
  }

  #content-text {
    color: #333 !important;
    font-weight: 500 !important;
  }

  /* ----- SCROLLBAR ----- */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(
      180deg,
      #ff3b30,
      #ffcc00,
      #34c759,
      #007aff,
      #ff2d55
    ) !important;
    border-radius: 20px;
  }
  ::-webkit-scrollbar-track {
    background: rgba(255,255,255,0.3) !important;
  }
}
